'use strict';

// Check the visible field labels generated by GitHub Issue Forms.
// Do not execute or interpolate any text supplied by issue authors.
const FORMS = Object.freeze({
  bug: {
    label: 'bug',
    prefix: '[Bug]',
    required: ['Bug summary', 'Steps to reproduce', 'Expected behavior', 'Support ID', 'Technical log'],
  },
  feature: {
    label: 'feature-request',
    prefix: '[Feature]',
    required: ['Feature summary', 'Problem or motivation', 'Proposed behavior', 'Support ID'],
  },
  feedback: {
    label: 'feedback',
    prefix: '[Feedback]',
    required: ['Feedback topic', 'Your feedback', 'Support ID'],
  },
});

const PLACEHOLDERS = new Set(['_no response_', 'no response', 'n/a', 'na', '-', 'none']);

function parseFields(body) {
  const fields = new Map();
  const sections = String(body || '').split(/^###\s+(.+?)\s*$/gm);
  for (let i = 1; i + 1 < sections.length; i += 2) {
    fields.set(sections[i].trim().toLowerCase(), sections[i + 1].trim());
  }
  return fields;
}

function hasContent(value) {
  const cleaned = String(value || '').replace(/```[\w-]*\s*\n?/g, '').replace(/```/g, '').trim();
  return cleaned.length > 0 && !PLACEHOLDERS.has(cleaned.toLowerCase());
}

function validateIssue(issue) {
  const title = String(issue.title || '').trim();
  const body = String(issue.body || '');
  const labels = (issue.labels || []).map(x => typeof x === 'string' ? x : x.name);
  const kinds = Object.entries(FORMS).filter(([, value]) => labels.includes(value.label));
  const errors = [];

  if (kinds.length !== 1) {
    errors.push('Select exactly one report label: `bug`, `feature-request`, or `feedback`.');
    return { valid: false, errors };
  }

  const [, form] = kinds[0];
  if (!title.startsWith(form.prefix) || !title.slice(form.prefix.length).trim()) {
    errors.push(`Set a descriptive title starting with \`${form.prefix}\`.`);
  }
  const fields = parseFields(body);
  for (const label of form.required) {
    if (!hasContent(fields.get(label.toLowerCase()))) {
      errors.push(`Fill in the **${label}** field.`);
    }
  }

  // A support ID is required but deliberately not tied to any account or character.
  // No UUID-format check yet: old addon versions cannot generate one.
  return { valid: errors.length === 0, errors };
}

module.exports = { validateIssue, parseFields, hasContent };
